const moveAllocation = `-- name: MoveAllocation :execrows
UPDATE vehicle_allocations
SET vehicle_id = $1
WHERE organization_id = $2
  AND id = $3
  AND vehicle_id = $4
  AND status = 'active'
`

type MoveAllocationParams struct {
	ToVehicleID    int64 `json:"to_vehicle_id"`
	OrganizationID int64 `json:"organization_id"`
	ID             int64 `json:"id"`
	FromVehicleID  int64 `json:"from_vehicle_id"`
}

// A reassignment step; matches only when the row is still where the plan
// found it (optimistic check: 0 rows = the plan is stale, retry).
func (q *Queries) MoveAllocation(ctx context.Context, arg MoveAllocationParams) (int64, error) {
	result, err := q.db.Exec(ctx, moveAllocation,
		arg.ToVehicleID,
		arg.OrganizationID,
		arg.ID,
		arg.FromVehicleID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

